public class ZipArchiveInputStream_getNextZipEntry_TriageGen0Test {

    private byte[] createLFH(String name, int method, boolean hasDataDescriptor, boolean isUtf8) {
        // Signature: 0x04034b50 (LFH_SIG)
        ByteBuffer bb = ByteBuffer.allocate(1024).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0x04034b50); 
        bb.putShort((short) 20); // version made by
        bb.putShort((short) 0);  // flags
        bb.putShort((short) method);
        bb.putInt(0); // time

        if (!hasDataDescriptor) {
            bb.putInt(0); // crc
            bb.putInt(0); // compressed size
            bb.putInt(0); // size
        } else {
            bb.putInt(0); // padding for data descriptor offset calculation
            bb.putInt(0);
            bb.putInt(0);
        }

        byte[] nameBytes = name.getBytes();
        bb.putShort((short) nameBytes.length);
        bb.putShort((short) 0); // extra len

        // Handle UTF8 flag in GPB
        if (isUtf8) {
            int currentPos = bb.position();
            bb.putShort(currentPos, (short) 0x8000); 
        }

        bb.put(nameBytes);

        byte[] result = new byte[bb.position()];
        bb.flip();
        bb.get(result);
        return result;
    }

    @Test
    public void testGetNextZipEntry_ClosedOrHitCentralDirectory() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        zis.close();
        assertNull(zis.getNextZipEntry());
    }
















}

